						const targetNode = cand && cand.nodeId ? findNodeById(tree, cand.nodeId) : null;
						/* 目标会话：只有"真有对话"的节点才有 —— 判据走 store/hierarchy.js 的单一真相源
						 * （`scopeHasConversation` / `scopeKeyOf`），不在这里各算各的。 */
