					...t,
					state: event.to,
					updatedAt: at,
					transitions: t.transitions.concat(event),
					error: event.to === STATE.FAILED ? (meta.note || t.error || "未说明原因") : t.error,
					pending: Object.prototype.hasOwnProperty.call(meta, "pending") ? meta.pending : t.pending
