						at: e.at,
						fromLabel: stateOf(e.from).label,
						toLabel: stateOf(e.to).label,
						label: stateOf(e.from).label + " → " + stateOf(e.to).label,
						note: e.note,
						waitMs: Math.max(0, e.at - prevAt)
